// Themed vocabulary clusters — words are grouped by real-life topic so the
// brain can chain them together (word-family / semantic clustering method).
// Each theme also carries a memory "hook" — a tiny mental image tying the
// group into one scene, following dual-coding + method-of-loci research.

export type VocabWord = {
  w: string; // English word
  bn: string; // Bangla meaning
  pos: string; // part of speech
  ex: string; // English example
  exBn: string; // Bangla translation of example
  tip?: string; // optional memory hook / pronunciation trick
};

export type VocabTheme = {
  id: string;
  title: string; // Bangla title
  titleEn: string; // English title
  emoji: string;
  scene: string; // one-line scene the learner should imagine
  hook: string; // Bangla memory-hook paragraph
  words: VocabWord[];
};

